"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8301],{86419:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CameraController","desc":"Manages the local player camera across three exclusive modes: aim (shoulder),\\nlocked third-person (movement-facing), and free-look (LeftAlt toggle). Mode\\nswitches are signal-driven \u2014 `Signals.RequestShootingCamera` enters or exits\\naim mode \u2014 and a MotionMaster spring smoothly eases `humanoid.CameraOffset`\\nbetween the aim and third-person positions. Mouse lock, `AutoRotate`, and the\\naim reticle are all reconciled in one `applyState` call so no state is\\never inconsistent.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/CameraController.client.luau"}}')}}]);